import { CommonModule } from '@angular/common';
import { AfterViewInit, Component, ElementRef, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { VariablesService } from '../../../core/services/variables.service';
import { IconComponent } from '../icon/icon.component';
import { INPUT_DEFAULTS, INPUT_FOCUS_OUT_FLAGS, InputFocusOutFlag, InputIcon } from '../../interfaces/input.interface';

@Component({
  selector: 'inpt',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent],
  templateUrl: './input.component.html',
  styleUrl: './input.component.scss'
})
export class InputComponent implements AfterViewInit {
  @Input() disabled = false;
  @Input() autofilloff = false;
  @Input() readonly = false;
  @Input() error = false;
  @Input() placeholder = '';
  @Input() isrequired = false;
  @Input() showlabel = true;
  @Input() isoutside = false;
  @Input() inlinemode = false;
  @Input() labelclas = '';
  @Input() inptclas = '';
  @Input() iconclas = '';
  @Input() type = 'text';
  @Input() maxlength: number = INPUT_DEFAULTS.MAX_LENGTH;
  @Input() icon?: InputIcon;
  @Input() value = '';
  @Input() focus = false;
  @Input() ids = '';

  @Output() readonly valueChange = new EventEmitter<string>();
  @Output() readonly focusOut = new EventEmitter<InputFocusOutFlag>();

  readonly INPUT_FOCUS_OUT_FLAGS = INPUT_FOCUS_OUT_FLAGS;

  showhide = false;

  @ViewChild('maininput') input?: ElementRef<HTMLInputElement>;

  constructor(public vs: VariablesService) {}

  ngAfterViewInit(): void {
    if (this.focus) {
      this.input?.nativeElement?.focus();
    }
  }

  get inputClasses() {
    if (this.disabled) {
      return `${this.inptclas} ${this.vs.inputvarnts.baseClasses} ${this.vs.inputvarnts.disabledClasses}`;
    }
    if (this.error) {
      return `${this.inptclas} ${this.vs.inputvarnts.baseClasses} ${this.vs.inputvarnts.errorClasses}`;
    }
    if (this.inlinemode) {
      return `${this.inptclas} ${this.vs.inputvarnts.baseClasses} ${this.vs.inputvarnts.inlineClasses}`;
    }

    return `${this.inptclas} ${this.vs.inputvarnts.baseClasses} ${this.vs.inputvarnts.normalClasses}`;
  }

  oninput(event: Event) {
    const target = event.target as HTMLInputElement | null;
    this.valueChange.emit(target?.value ?? '');
  }

  focusOuts(flag: InputFocusOutFlag) {
    this.focusOut.emit(flag);
  }
}
